def alternate_case(text):
    result = ''
    for i, character in enumerate(text):     # i counts 0, 1, 2, ... as the loop walks the string
        if i % 2 == 0:
            result = result + character.lower()
        else:
            result = result + character.upper()
    return result

print(alternate_case('Hello, world!'))

